def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_moves = [h[0] for h in history]
    opp_moves = [h[1] for h in history]

    my_d = my_moves.count('D')
    opp_d = opp_moves.count('D')
    opp_c = n - opp_d

    if opp_d == n:
        return 'D'

    if opp_d == 0:
        # Exploit a non-defecting opponent with a safe 10% defection rate.
        if n >= 10 and n % 10 == 0:
            return 'D'
        return 'C'

    # Core logic for opponents that have defected at least once.
    coop_rate = opp_c / n

    # Opponent's current defection streak.
    opp_streak_d = 0
    for m, o in reversed(history):
        if o == 'D':
            opp_streak_d += 1
        else:
            break

    # Opponent's current cooperation streak.
    opp_streak_c = 0
    for m, o in reversed(history):
        if o == 'C':
            opp_streak_c += 1
        else:
            break

    # Punish consecutive defections.
    if opp_streak_d >= 2:
        return 'D'

    # Opponent just defected once.
    if opp_streak_d == 1:
        # Forgive if they have been very cooperative and it's an isolated defection.
        if coop_rate > 0.7 and opp_streak_c >= 3:
            return 'C'
        if n >= 4 and history[-3][1] == 'C' and history[-4][1] == 'C':
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    if coop_rate >= 0.8:
        return 'C'
    if coop_rate > 0.6:
        # Occasionally defect to probe, but rarely.
        if rng.random() < 0.05:
            return 'D'
        return 'C'
    if coop_rate > 0.5:
        if rng.random() < 0.3:
            return 'C'
        return 'D'
    return 'D'
